const item = $input.first().json;

// Quita etiquetas <correo> del texto, para que nadie pueda cerrar el bloque y colar instrucciones
const limpiar = (t) => String(t ?? '').replace(/<\/?correo>/gi, '');

const texto =
  'Analiza el siguiente correo.\n\n<correo>\n' +
  'De: ' + limpiar(item.Nombre) + ' <' + limpiar(item.Email) + '>\n' +
  'Asunto: ' + limpiar(item.Asunto) + '\n' +
  'Mensaje: ' + limpiar(item.Mensaje) + '\n</correo>';

return [{ json: { ...item, email_text: texto } }];

