parameters.jsCode:
const original = $('Preparar petición IA').first().json;
const r = $input.first().json;

// Admite la respuesta de Groq (formato OpenAI) y la de Gemini
const raw = r.choices?.[0]?.message?.content ?? r.candidates?.[0]?.content?.parts?.[0]?.text;

let ai = {};
let parse_error = false;
try {
  ai = JSON.parse(raw);
} catch (e) {
  parse_error = true;
}

return [{ json: { ...ai, ...original, parse_error } }];

const d = $input.first().json;

const categorias = ['presupuesto', 'informacion', 'pedido', 'reclamacion', 'otra'];
const prioridades = ['baja', 'media', 'alta'];
const camposTexto = ['category', 'priority', 'customer_name', 'company', 'requested_service', 'quantity', 'summary', 'draft_reply'];

const errores = [];
const avisos = [];

// 1. ¿La respuesta de la IA tiene la forma correcta?
if (d.parse_error) {
  errores.push('La IA no devolvió un JSON legible');
} else {
  for (const campo of camposTexto) {
    if (typeof d[campo] !== 'string') errores.push('Falta o no es texto: ' + campo);
  }
  if (!Array.isArray(d.missing_information) || d.missing_information.some(x => typeof x !== 'string')) {
    errores.push('missing_information debe ser una lista de textos');
  }
  if (typeof d.human_review_required !== 'boolean') {
    errores.push('human_review_required debe ser true o false');
  }
  if (!categorias.includes(d.category)) errores.push('Categoría no permitida: ' + d.category);
  if (!prioridades.includes(d.priority)) errores.push('Prioridad no permitida: ' + d.priority);
}

const valido = errores.length === 0;
let priority = valido ? d.priority : '';
let revision = valido ? d.human_review_required : true;

// 2. Reglas sobre el correo, se aplican siempre
let manipulacion = false;
const textoCliente = (d.Asunto || '') + ' ' + (d.Mensaje || '');
if (/ignor[ae]\s+(tus|las|todas)|instrucciones anteriores|ignore\s+(all|your|previous)|system prompt|prompt del sistema|olvida\s+(todo|tus|las)/i.test(textoCliente)) {
  revision = true;
  manipulacion = true;
  avisos.push('Posible intento de manipulación en el correo');
}
if (/\[número oculto\]|\b(iban|cvv|cvc)\b|contraseña|número de tarjeta|datos de (la )?tarjeta|tarjeta de (crédito|débito)/i.test(textoCliente)) {
  revision = true;
  avisos.push('El correo contiene datos de pago o credenciales');
}

// 3. Reglas sobre la respuesta, solo si es válida
if (valido) {
  if (d.category === 'reclamacion') {
    priority = 'alta';
    revision = true;
    avisos.push('Reclamación: prioridad alta y revisión obligatoria');
  }
  // Si el correo da órdenes a la IA, la prioridad no puede salir de esas órdenes:
  // la fija el código según la categoría
  if (manipulacion && d.category !== 'reclamacion') {
    const porDefecto = { presupuesto: 'media', pedido: 'media', informacion: 'baja', otra: 'baja' };
    const fijada = porDefecto[d.category];
    if (fijada && priority !== fijada) {
      avisos.push('Prioridad fijada por el código (' + fijada + '): el correo intenta dar órdenes a la IA');
    }
    if (fijada) priority = fijada;
  }
  if (d.category === 'informacion') {
    revision = true;
    avisos.push('Consulta de información: debe responderla una persona con datos de la empresa');
  }
  if (d.missing_information.length > 0) {
    avisos.push('Información incompleta');
  }
  if (/\d+\s?%|€|\$|\beuros?\b|descuento|gratis|gratuit|garantiz|precio/i.test(d.draft_reply)) {
    revision = true;
    avisos.push('El borrador menciona precios, descuentos o garantías');
  }
  if (/asegur|antes del|antes de que|en \d+ (días|horas|semanas)|para el (lunes|martes|miércoles|jueves|viernes|sábado|domingo)/i.test(d.draft_reply)) {
    revision = true;
    avisos.push('El borrador menciona plazos o fechas de entrega');
  }
  if (/\b\d{1,2}[:.]\d{2}\b|\bde (lunes|martes|miércoles|jueves|viernes|sábado|domingo) a (lunes|martes|miércoles|jueves|viernes|sábado|domingo)/i.test(d.draft_reply)) {
    revision = true;
    avisos.push('El borrador afirma datos de la empresa (horarios u otros)');
  }
  if (/disponemos|tenemos (disponible|en stock|existencias)|hay (stock|existencias|disponibilidad)|en stock|stock disponible/i.test(d.draft_reply)) {
    revision = true;
    avisos.push('El borrador afirma disponibilidad o existencias');
  }
  if (/\b(sí,?|si,)\s+(ofrecemos|hacemos|realizamos|imprimimos|fabricamos|vendemos|trabajamos|enviamos)|(?<!\bsi\s)\b(ofrecemos|imprimimos|fabricamos|vendemos)\s+(el |la |los |las |un |una )?\w+/i.test(d.draft_reply)) {
    revision = true;
    avisos.push('El borrador afirma que la empresa ofrece un producto o servicio');
  }
}

// 4. Estado final
let status = 'pendiente_revision';
if (!valido) status = 'error_validacion';
else if (d.missing_information.length > 0) status = 'incompleta';

return [{
  json: {
    ...d,
    category: valido ? d.category : '',
    summary: valido ? d.summary : '',
    priority,
    human_review_required: revision,
    valid: valido,
    validation_errors: errores,
    validation_flags: avisos,
    status
  }
}];

// Oculta secuencias de 13 a 19 cifras (posibles números de tarjeta) antes de guardarlas o enviarlas a la IA
const ocultar = (t) => String(t ?? '').replace(/\b(?:\d[ -]?){12,18}\d\b/g, '[número oculto]');

return $input.all().map((entrada) => {
  const m = entrada.json;
  const remitente = (m.from && m.from.value && m.from.value[0]) || {};
  return {
    json: {
      request_id: m.id,
      received_at: m.date,
      Nombre: remitente.name || remitente.address || '',
      Email: remitente.address || '',
      Asunto: ocultar(m.subject),
      Mensaje: ocultar((m.text || '').trim()),
      status: 'recibida'
    }
  };
});

